-- name: CreateScheduledActivityCapture :one
-- Auto-generated by the scheduler worker when a fixed schedule fires.
-- occurred_at is set equal to scheduled_at at creation time.
-- ON CONFLICT mirrors uq_activity_captures_activity_scheduled_at exactly,
-- so a duplicate generation attempt (e.g. two worker instances racing)
-- is silently ignored instead of erroring.
INSERT INTO activity_captures(
    activity_id,
    schedule_id,
    status,
    scheduled_at,
    occurred_at
) VALUES (
    sqlc.arg(activity_id),
    sqlc.arg(schedule_id),
    'awaiting',
    sqlc.arg(scheduled_at),
    sqlc.arg(scheduled_at)
)
ON CONFLICT(activity_id, scheduled_at) WHERE deleted_at IS NULL DO NOTHING
    RETURNING *;

-- name: CreateManualActivityCapture :one
-- User-logged item for a non-fixed-schedule activity, created directly
-- as 'captured' or 'missed' (never 'awaiting'). occurred_at may be
-- backdated by the user; scheduled_at/schedule_id stay NULL.
    INSERT INTO activity_captures(
        activity_id,
        status,
        occurred_at,
        content,
        color_hex
    ) VALUES (
        sqlc.arg(activity_id),
        sqlc.arg(status),
        sqlc.arg(occurred_at),
        sqlc.narg(content),
        sqlc.narg(color_hex)
    )
    RETURNING *;

-- name: GetActivityCaptureByID :one
    SELECT * FROM activity_captures
    WHERE id = sqlc.arg(id) AND deleted_at IS NULL;

-- name: ListActivityCapturesByActivityID :many
-- Timeline/history view for one activity, newest occurrence first.
    SELECT * FROM activity_captures
    WHERE activity_id = sqlc.arg(activity_id) AND deleted_at IS NULL
    ORDER BY occurred_at DESC
    LIMIT sqlc.arg(page_limit)
    OFFSET sqlc.arg(page_offset);

-- name: ConfirmActivityCapture :one
-- User checks an awaiting item off as done or not done, optionally with
-- a moment (content/color). "WHERE status = 'awaiting'" avoids a race
-- against the timeout job flipping the same row at the same time.
    UPDATE activity_captures
    SET status = sqlc.arg(status),
        confirmed_at = NOW(),
        content = sqlc.narg(content),
        color_hex = sqlc.narg(color_hex),
        updated_at = NOW()
    WHERE id = sqlc.arg(id) AND status = 'awaiting'
        RETURNING *;

-- name: UpdateActivityCaptureMoment :one
-- Edit the logged moment (content/color) after the fact, without
-- touching status/confirmed_at.
    UPDATE activity_captures
    SET content = sqlc.narg(content),
        color_hex = sqlc.narg(color_hex),
        updated_at = NOW()
    WHERE id = sqlc.arg(id)
        AND deleted_at IS NULL
        RETURNING *;

-- name: ListAwaitingItemsPastDeadline :many
-- Candidates the timeout worker is about to flip to 'missed'; useful for
-- notifying the user beforehand, logging, etc. Mirrors the condition in
-- MarkOverdueItemsAsMissed below.
    SELECT activity_captures.*
    FROM activity_captures
        JOIN activities ON activities.id = activity_captures.activity_id
    WHERE activity_captures.status = 'awaiting'
        AND activity_captures.deleted_at IS NULL
        AND activities.deleted_at IS NULL
        AND activities.confirmation_timeout_minutes IS NOT NULL
        AND activity_captures.scheduled_at
        + (activities.confirmation_timeout_minutes | | ' minutes') ::interval < NOW();

-- name: MarkOverdueItemsAsMissed :execrows
-- The timeout job itself: bulk-flip every 'awaiting' item whose deadline
-- (scheduled_at + activities.confirmation_timeout_minutes) has passed.
-- Run this on a schedule (e.g. every minute).
    UPDATE activity_captures
    SET status = 'missed',
        updated_at = NOW()
    FROM activities
    WHERE activities.id = activity_captures.activity_id
        AND activity_captures.status = 'awaiting'
        AND activity_captures.deleted_at IS NULL
        AND activities.deleted_at IS NULL
        AND activities.confirmation_timeout_minutes IS NOT NULL
        AND activity_captures.scheduled_at
        + (activities.confirmation_timeout_minutes | | ' minutes') ::interval < NOW();

-- name: SoftDeleteActivityCapture :exec
    UPDATE activity_captures
    SET deleted_at = NOW()
    WHERE id = sqlc.arg(id)
        AND deleted_at IS NULL;

-- name: RestoreActivityCapture :exec
    UPDATE activity_captures
    SET deleted_at = NULL
    WHERE id = sqlc.arg(id);

-- name: GetHeatmapData :many
-- GitHub-contribution-graph-style data: item count per day, bucketed in
-- the user's own timezone (users.timezone), across all of that user's
-- activities, between [from_date, to_date).
    SELECT
        (activity_captures.occurred_at AT TIME ZONE users.timezone) ::date AS day,
        COUNT(*) ::bigint AS item_count
    FROM activity_captures
        JOIN activities ON activities.id = activity_captures.activity_id
        JOIN users ON users.id = activities.user_id
    WHERE activities.user_id = sqlc.arg(user_id)
        AND activity_captures.deleted_at IS NULL
        AND activities.deleted_at IS NULL
        AND activity_captures.occurred_at >= sqlc.arg(from_date)
        AND activity_captures.occurred_at < sqlc.arg(to_date)
    GROUP BY day
    ORDER BY day;

-- name: GetConfirmationDelayStats :many
-- "Waktu muncul -> konfirmasi" chart for one fixed-schedule activity:
-- how long after scheduled_at did the user actually confirm each item.
    SELECT
        id,
        scheduled_at,
        confirmed_at,
        EXTRACT(EPOCH FROM (confirmed_at - scheduled_at)) ::bigint AS delay_seconds
    FROM activity_captures
    WHERE activity_id = sqlc.arg(activity_id)
        AND deleted_at IS NULL
        AND scheduled_at IS NOT NULL
        AND confirmed_at IS NOT NULL
    ORDER BY scheduled_at;